invocation.command:
set -eu
command -v mempal >/dev/null 2>&1 || { printf '%s\n' "[mempal] Docker image does not contain mempal. Build memorybench-codex-mempal:0.144.1-r5-0.9.0-r2 with pnpm docker:mempal codex, then use that image." >&2; exit 1; }
test -n "$(find "$HOME/.cache/huggingface" -name "*.safetensors" -print -quit 2>/dev/null)" || { printf '%s\n' '[mempal] embedding cache probe failed' >&2; exit 1; }

